 function scheduleSearch(immediate=false){clearTimeout(searchTimer);searchController?.abort();const version=++searchVersion,query=$('news-search').value.trim();searchPending=query.length>=2&&query.length<=160;publicArticles=[];combineResults();render();searchStatus.textContent='';if(!query)return;if(query.length<2){searchStatus.textContent='Escribe al menos 2 caracteres para buscar en fuentes públicas.';return;}if(query.length>160){searchStatus.textContent='Usa hasta 160 caracteres para buscar.';return;}searchStatus.textContent='Buscando en fuentes públicas…';searchTimer=setTimeout(async()=>{const controller=new AbortController();searchController=controller;const timer=setTimeout(()=>controller.abort(),15000);try{const r=await fetch('/.netlify/functions/news-search?q='+encodeURIComponent(query),{signal:controller.signal});if(!r.ok)throw Error(r.status===429?'rate':'search');const data=await r.json();if(version!==searchVersion)return;searchPending=false;publicArticles=data.articles.map(a=>({...a,capturedAt:data.updatedAt}));combineResults();searchStatus.textContent=`${publicArticles.length} resultados en fuentes públicas · ${data.provider} · hasta ${data.limit} noticias. Los filtros se aplican a estos resultados.`;render();syncSocial();}catch(error){if(version!==searchVersion)return;searchPending=false;render();searchStatus.textContent=error.message==='rate'?'Espera un momento para volver a buscar. Se conservan las coincidencias del feed.':'No se pudo consultar las fuentes públicas. Se conservan las coincidencias del feed. ';const retry=document.createElement('button');retry.textContent='Reintentar búsqueda';retry.onclick=()=>scheduleSearch(true);searchStatus.append(retry);}finally{clearTimeout(timer);}},immediate?0:500);}

