 function render(){const pendingRows=candidates(),preparing=pendingRows.some(a=>!hasCompleteReading(readings.get(a))&&readings.isPending(a));const rows=filtered();discoveryBar.hidden=!selection;if(selection){discoveryBar.innerHTML=`<strong>${selection.tag?'Relacionadas con #'+esc(selection.tag):selection.place.scope==='country'?'Misma referencia: '+esc(selection.place.label):'Cerca de '+esc(selection.place.label)}</strong><span>${rows.length} noticias del feed disponible${selection.place?' · ubicación aproximada':''}</span>${selection.place?.scope==='local'?'<label>Radio <select id="discovery-radius"><option value="50">50 km</option><option value="100">100 km</option><option value="250">250 km</option></select></label>':''}<button id="follow-discovery">${followState.rows.some(r=>r.kind===(selection.tag?'tag':'place')&&r.value===(selection.tag||selection.place.label))?'✓ Siguiendo · dejar de seguir':'＋ Seguir'}</button><button id="clear-discovery">Quitar filtro</button>`;if($('discovery-radius')){$('discovery-radius').value=selection.radius;$('discovery-radius').onchange=e=>{selection.radius=Number(e.target.value);render();};}$('follow-discovery').onclick=()=>toggleFollow(selection.tag?'tag':'place',selection.tag||selection.place.label);$('clear-discovery').onclick=()=>{selection=null;render();};}onNews(rows.map(newsEvidence));$('news-feed').innerHTML=rows.slice(0,limit).map(a=>{const c=counts.get(a.id);const place=locateHeadline(a.title);const topicName=topics.find(t=>t.id===a.topics[0])?.label||'Actualidad';return `<article class="news-card theme-${esc(a.topics[0])}" data-photo-id="${a.id}" data-search-query="${esc(a.searchQuery||'')}" data-headline="${esc(a.title)}"><div class="story-art" hidden></div><div class="story-body"><div class="news-byline"><span>${esc(a.source)}</span><time datetime="${esc(a.publishedAt)}">${esc(date(a.publishedAt))}</time></div><h2><a data-read="${a.id}" href="${esc(safe(a.url))}">${esc(a.title)}</a></h2>${discoveryMarkup(a,esc)}<div class="news-actions"><button data-like="${a.id}" aria-pressed="${liked.has(a.id)}">${liked.has(a.id)?'♥':'♡'} <span>${c?c.likes:'—'}</span> Me gusta</button><button data-comments="${a.id}">☏ ${c?c.comments:'—'} Comentar</button><button data-share="${a.id}">↗ Compartir</button><button data-research="${a.id}">Investigar +</button><button data-news-map="${a.id}">◎ Ver en mapa</button><button data-read="${a.id}" class="read-story">${readings.get(a)?'Leer síntesis lista →':'Leer síntesis y contexto →'}</button></div></div></article>`}).join('')||`<div class="empty"><h2>${(searchPending||preparing)?'<span class="loading-label"><span class="loading-spinner" aria-hidden="true"></span>Buscando noticias…</span>':followingOnly?'Tu lectura, a tu ritmo':'Sin noticias para estos filtros'}</h2><p>${(searchPending||preparing)?'Consultando fuentes públicas.':followingOnly?'Sigue temas, hashtags o lugares desde las tarjetas. Aquí aparecerán sus noticias cuando estén disponibles en el feed.':'Prueba otro tema, medio o periodo.'}</p></div>`;$('more-news').hidden=rows.length<=limit;
 $('news-feed').querySelectorAll('[data-like]').forEach(b=>b.onclick=()=>like(b.dataset.like,b));$('news-feed').querySelectorAll('[data-comments]').forEach(b=>b.onclick=()=>openComments(b.dataset.comments));$('news-feed').querySelectorAll('[data-share]').forEach(b=>b.onclick=()=>share(b.dataset.share));$('news-feed').querySelectorAll('[data-read]').forEach(b=>b.onclick=e=>{e.preventDefault();openReader(articles.find(a=>a.id===b.dataset.read));});bindDiscovery($('news-feed'));bindResearch();enhancePhotos($('news-feed'));prepareReadings($('news-feed'),pendingRows);}
